import{_ as a,c as e,o as t,a2 as s}from"./chunks/framework.DdOM6S6U.js";const v=JSON.parse('{"title":"Coverage Watch","description":"","frontmatter":{"sidebarPos":6,"sidebarTitle":"Coverage Watch"},"headers":[],"relativePath":"guide/console/coverage/coverage-watch.md","filePath":"guide/console/coverage/coverage-watch.md","lastUpdated":1777448680000}'),i={name:"guide/console/coverage/coverage-watch.md"},o=s(`<h1 id="coverage-watch" tabindex="-1">Coverage Watch <a class="header-anchor" href="#coverage-watch" aria-label="Permalink to &quot;Coverage Watch&quot;">​</a></h1><blockquote><p>Poll a Clover XML file and display a diff whenever coverage changes — useful for a live TDD feedback loop.</p></blockquote><h2 id="command-information" tabindex="-1">Command Information <a class="header-anchor" href="#command-information" aria-label="Permalink to &quot;Command Information&quot;">​</a></h2><ul><li><strong>Signature:</strong> <code>coverage:watch [--cloverName=] [--cloverDir=] [--interval=5]</code></li><li><strong>Category:</strong> Coverage</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table><thead><tr><th>Option</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--cloverName</code></td><td><code>clover.xml</code></td><td>Clover XML file name to watch</td></tr><tr><td><code>--cloverDir</code></td><td><code>storage/app</code></td><td>Directory containing the Clover file</td></tr><tr><td><code>--interval</code></td><td><code>5</code></td><td>Polling interval in seconds</td></tr></tbody></table><h2 id="what-it-does" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What It Does&quot;">​</a></h2><p>The command reads the Clover file on startup and saves the initial coverage snapshot. It then re-reads the file every <code>--interval</code> seconds. When coverage numbers change — either because tests were re-run or because the file was regenerated — it prints a diff showing which files improved or regressed.</p><p>Press <code>Ctrl+C</code> to stop watching.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><h3 id="watch-with-default-settings" tabindex="-1">Watch with default settings <a class="header-anchor" href="#watch-with-default-settings" aria-label="Permalink to &quot;Watch with default settings&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coverage:watch</span></span></code></pre></div><h3 id="check-every-2-seconds" tabindex="-1">Check every 2 seconds <a class="header-anchor" href="#check-every-2-seconds" aria-label="Permalink to &quot;Check every 2 seconds&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coverage:watch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --interval=2</span></span></code></pre></div><h3 id="watch-a-custom-clover-file" tabindex="-1">Watch a custom Clover file <a class="header-anchor" href="#watch-a-custom-clover-file" aria-label="Permalink to &quot;Watch a custom Clover file&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coverage:watch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cloverDir=build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cloverName=coverage.xml</span></span></code></pre></div><h2 id="tdd-workflow" tabindex="-1">TDD Workflow <a class="header-anchor" href="#tdd-workflow" aria-label="Permalink to &quot;TDD Workflow&quot;">​</a></h2><p>Keep the watcher running in a terminal split while you write tests:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 1 — run tests continuously</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --coverage-clover=storage/app/clover.xml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --watch</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 2 — watch coverage change in real time</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coverage:watch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --interval=3</span></span></code></pre></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/console/coverage/coverage-analyze">coverage:analyze</a> — one-shot analysis</li><li><a href="/guide/console/coverage/coverage-generate-tests">coverage:generate-tests</a> — scaffold missing tests</li></ul>`,21),l=[o];function n(h,r,c,d,p,g){return t(),e("div",null,l)}const u=a(i,[["render",n]]);export{v as __pageData,u as default};
